#include <memory>
#include <typeindex>
#include <unordered_map>

class Registry
{
private:
    std::vector<std::uint32_t>
        m_Generations;

    std::vector<bool>
        m_Alive;

    std::vector<std::uint32_t>
        m_Free;

    std::unordered_map<
        std::type_index,
        std::unique_ptr<IComponentPool>>
        m_Pools;
};

Entity Create()
{
    std::uint32_t index;

    if (!m_Free.empty())
    {
        index = m_Free.back();
        m_Free.pop_back();

        assert(
            index < m_Alive.size());

        assert(
            !m_Alive[index]);

        m_Alive[index] = true;
    }
    else
    {
        if (m_Generations.size() >=
            Entity::InvalidIndex)
        {
            throw std::overflow_error(
                "Entity index space exhausted.");
        }

        index =
            static_cast<std::uint32_t>(
                m_Generations.size());

        m_Generations.push_back(1);

        try
        {
            m_Alive.push_back(true);
        }
        catch (...)
        {
            m_Generations.pop_back();
            throw;
        }
    }

    return
    {
        index,
        m_Generations[index]
    };
}

bool Destroy(Entity entity)
{
    if (!IsAlive(entity))
    {
        return false;
    }

    // Remove old generation's components before
    // allowing slot to become a new entity.
    for (auto& [_, pool] : m_Pools)
    {
        pool->Remove(entity);
    }

    m_Alive[entity.Index] = false;

    std::uint32_t& generation =
        m_Generations[entity.Index];

    if (generation !=
        std::numeric_limits<
            std::uint32_t>::max())
    {
        ++generation;
        m_Free.push_back(entity.Index);
    }
    else
    {
        // Retire permanently rather than wrap.
    }

    return true;
}

template<typename T>
ComponentPool<T>& Pool()
{
    const std::type_index key =
        std::type_index(typeid(T));

    const auto found =
        m_Pools.find(key);

    if (found != m_Pools.end())
    {
        return *static_cast<
            ComponentPool<T>*>(
                found->second.get());
    }

    auto created =
        std::make_unique<
            ComponentPool<T>>();

    ComponentPool<T>* pointer =
        created.get();

    m_Pools.emplace(
        key,
        std::move(created));

    return *pointer;
}

template<typename T, typename... Args>
T& Emplace(
    Entity entity,
    Args&&... args)
{
    if (!IsAlive(entity))
    {
        throw std::invalid_argument(
            "Cannot mutate stale entity.");
    }

    return Pool<T>()
        .Storage
        .Emplace(
            entity,
            std::forward<Args>(
                args)...);
}

template<
    typename A,
    typename B,
    typename Function>
void Each(Function&& function)
{
    auto& a = Pool<A>().Storage;
    auto& b = Pool<B>().Storage;

    if (a.Size() <= b.Size())
    {
        const auto& entities =
            a.Entities();

        auto& values =
            a.Components();

        for (std::size_t i = 0;
             i < entities.size();
             ++i)
        {
            Entity entity = entities[i];

            if (B* second =
                    b.TryGet(entity))
            {
                std::invoke(
                    function,
                    entity,
                    values[i],
                    *second);
            }
        }
    }
    else
    {
        const auto& entities =
            b.Entities();

        auto& values =
            b.Components();

        for (std::size_t i = 0;
             i < entities.size();
             ++i)
        {
            Entity entity = entities[i];

            if (A* first =
                    a.TryGet(entity))
            {
                // Preserve caller's requested order.
                std::invoke(
                    function,
                    entity,
                    *first,
                    values[i]);
            }
        }
    }
}

