struct TraversalEntry
{
    std::uint32_t nodeIndex;
    float nearT;
};

template <class PrimitiveIntersector>
std::optional<Hit> closestHitBVH(
    const BVH& bvh,
    const Ray& ray,
    PrimitiveIntersector&& intersectPrimitive,
    float maxDistance)
{
    if (bvh.nodes.empty())
        return std::nullopt;

    std::array<TraversalEntry, 128> stack{};
    std::size_t stackSize = 0;

    float rootNear = 0.0f;

    if (!intersectAABB(
            ray,
            bvh.nodes[0].bounds,
            maxDistance,
            rootNear))
    {
        return std::nullopt;
    }

    stack[stackSize++] =
        {0u, rootNear};

    float closest =
        maxDistance;

    std::optional<Hit> best;

    while (stackSize != 0)
    {
        const TraversalEntry current =
            stack[--stackSize];

        // The box was already tested when inserted.
        // Since closest may have decreased meanwhile,
        // one scalar test can now prune the node.
        if (current.nearT > closest)
            continue;

        const BVHNode& node =
            bvh.nodes[current.nodeIndex];

        if (node.isLeaf())
        {
            for (std::uint32_t i = 0;
                 i < node.primitiveCount;
                 ++i)
            {
                const std::uint32_t primitive =
                    bvh.primitiveOrder[
                        node.firstPrimitive + i];

                auto hit =
                    intersectPrimitive(
                        primitive,
                        ray,
                        closest);

                if (!hit)
                    continue;

                if (hit->distance < 0.0f ||
                    hit->distance > closest)
                    continue;

                closest = hit->distance;
                best = *hit;
            }

            continue;
        }

        float leftNear = 0.0f;
        float rightNear = 0.0f;

        const bool hitLeft =
            intersectAABB(
                ray,
                bvh.nodes[node.left].bounds,
                closest,
                leftNear);

        const bool hitRight =
            intersectAABB(
                ray,
                bvh.nodes[node.right].bounds,
                closest,
                rightNear);

        if (hitLeft && hitRight)
        {
            // Push far first because stack is LIFO.
            if (leftNear <= rightNear)
            {
                stack[stackSize++] =
                    {node.right, rightNear};

                stack[stackSize++] =
                    {node.left, leftNear};
            }
            else
            {
                stack[stackSize++] =
                    {node.left, leftNear};

                stack[stackSize++] =
                    {node.right, rightNear};
            }
        }
        else if (hitLeft)
        {
            stack[stackSize++] =
                {node.left, leftNear};
        }
        else if (hitRight)
        {
            stack[stackSize++] =
                {node.right, rightNear};
        }
    }

    return best;
}

