void insert(
    QuadNode& node,
    Item item)
{
    // If children exist and one completely
    // contains the item, descend.
    if (node.hasChildren())
    {
        if (QuadNode* child =
                containingChild(
                    node,
                    item.bounds))
        {
            insert(*child, item);
            return;
        }
    }

    node.items.push_back(item);

    // Split only after capacity is exceeded
    // and maximum depth is not reached.
    if (node.items.size() >
            MaxItemsPerNode &&
        node.depth < MaxDepth)
    {
        if (!node.hasChildren())
            subdivide(node);

        redistributeItems(node);
    }
}

